L[". Ctrl+C to copy it, then send it in a support request on Discord to be added."] = "。按 Ctrl+C 複製，然後在 Discord 上提交支援請求以加入。"
L[". Ctrl+C to copy it, then send it to the team on Discord to be added."] = "。按 Ctrl+C 複製，然後在 Discord 上傳給團隊以加入。"
L[". Make first: "] = "。先製作： "
L[". Open the mailbox on those characters to keep it."] = "。在那些角色上開啟郵箱以保留它。"
L[". Unlock its window to drag and resize it, or place it in the HUD Editor."] = "。解鎖其視窗以拖曳並調整大小，或在 HUD 編輯器中放置。"
L["... and %d more"] = "...以及另外 %d 個"
L["/copy puts the text of whatever is under your cursor in a box you can copy from. /copy followed by a frame name copies that frame's text instead."] = "/copy 會把游標下任何東西的文字放到可複製的方框中。/copy 後面加上框架名稱則改為複製該框架的文字。"
L["/nf ab <name>: imports a saved action bar set; /nf ab lists them"] = "/nf ab <name>：匯入已儲存的快捷列組合；/nf ab 會列出它們"
L["/nf badges id: your badge claim code"] = "/nf badges id：你的徽章領取碼"
L["/nf bars save, restore, test or delete <name>: your action bar sets; /nf bars list lists them"] = "/nf bars save、restore、test 或 delete <name>：你的快捷列組合；/nf bars list 會列出它們"
L["/nf lockouts: your raid and dungeon lockouts"] = "/nf lockouts：你的團隊副本與地城鎖定"
L["/nf move (or /nf hud): opens or closes the HUD Editor"] = "/nf move（或 /nf hud）：開啟或關閉 HUD 編輯器"
L["/nf quiz: the WoW quiz"] = "/nf quiz：魔獸問答"
L["/nf ranks: higher ranks to put on your bars"] = "/nf ranks：可放上快捷列的更高等級法術"
L["/nf junk: the Junk List"] = "/nf junk：垃圾清單"
L["/nf trainer: a waypoint to your nearest class trainer"] = "/nf trainer：前往最近職業訓練師的導航點"
L["/nf xp start, pause or reset: the XP ticker"] = "/nf xp start、pause 或 reset：經驗值計數器"
L["/nf: opens the settings"] = "/nf：開啟設定"
L["/nfquests (or /nfcompleto): the Quest List, in Discovery"] = "/nfquests（或 /nfcompleto）：探索中的任務清單"
L["0 keeps it up until you close it."] = "0 表示會一直顯示直到你關閉。"
L["1 %s is worth %g to %s."] = "對 %3$s 來說，1 %1$s 相當於 %2$g。"
L["1 book"] = "1 本書"
L["1 consumable"] = "1 個消耗品"
L["1 consumable watched"] = "1 個消耗品監看中"
L["1 craft"] = "1 次製作"
L["1 day"] = "1 天"
L["1 dungeon"] = "1 個地城"
L["1 hour"] = "1 小時"
L["1 in %d"] = "%d 分之 1"
L["1 item on the bar"] = "列上有 1 件物品"
L["1 minute"] = "1 分鐘"
L["1 paladin in your group"] = "隊伍中有 1 名聖騎士"
L["1 player has their own blessing"] = "1 名玩家有自己的祝福"
L["1 profile on this account"] = "此帳號有 1 個設定檔"
L["1 raid"] = "1 個團隊副本"
L["1 runs Naowh Forever"] = "1 人使用 Naowh Forever"
L["1 setting changed from its default"] = "1 項設定已不同於預設值"
L["1 spell"] = "1 個法術"
L["1 Unspent Talent Point"] = "1 點未分配的天賦點數"
L["1. PICK YOUR BARS"] = "1. 選擇你的快捷列"
L["100%  (default)"] = "100%  （預設）"
L["100%, native resolution"] = "100%，原生解析度"
L["12-hour clock"] = "12 小時制"
L["16x Anisotropic"] = "16x 非等向性過濾"
L["2. ALSO KEEP"] = "2. 同時保留"
L["24-Hour Clock"] = "24 小時制"
L["24-hour clock"] = "24 小時制"
L["3. NAME AND SAVE"] = "3. 命名並儲存"
L["30, while the game is not in focus"] = "30，遊戲不在前景時"
L[": copy ID or Wowhead link"] = "：複製 ID 或 Wowhead 連結"
L[": mail expiring soon on "] = "：即將過期的郵件於 "
L["; buys at vendors"] = "；向商人購買"
L["<AFK>"] = "<暫離>"
L["<DND>"] = "<忙碌>"
L["[Where?]"] = "[在哪？]"
L["A /thank to everyone around you when the game cannot name the caster."] = "當遊戲無法得知施法者名稱時，向周圍所有人 /thank。"
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "收到所在區域不明的人的密語後，顯示 [在哪？] 連結。點擊會對其執行 /who 並顯示其區域；之後的訊息都會加上標記。"
L["A banner and a sound when one of them joins your group."] = "他們之一加入你的隊伍時顯示橫幅並播放音效。"
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "在你會拉到仇恨的威脅值處顯示一條線，方便看出差距。"
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "顯示目標揮擊的計時條，在它以你為目標時每次受到物理攻擊就重新開始，被招架時則縮短。這只是估計：遊戲不會告訴你是誰用什麼打你，因此其他攻擊者、物理特殊技能和流血跳傷也會重置它。"
L["A bar left out is not touched by an import."] = "未選取的快捷列不會被匯入影響。"
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "每位隊伍成員一條計量條，顯示其等級和升級進度。所有使用 Naowh Forever 的成員都會分享經驗值，即使此選項關閉；其他人則顯示等級。更新會等到戰鬥結束。在 HUD 編輯器中移動。"
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "設定導航點時，顯示含名稱、轉向箭頭和距離的計量條。"
L["A batch of ten, four done, as it shows while you craft."] = "一批十個、已完成四個，如同製作時的顯示。"
L["A black outline round the clock."] = "時鐘周圍的黑色外框。"
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "FPS / MS 讀數和計數周圍的黑色外框，取代柔和陰影。"
L["A black outline round the text, in place of the soft shadow."] = "文字周圍的黑色外框，取代柔和陰影。"
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "每個組合一個按鈕：點擊裝備，Shift-點擊把身上的裝備存入，Ctrl-點擊重新命名，右鍵點擊更換圖示，按 + 儲存新組合。目前穿著的組合會加上外框。在 HUD 編輯器中移動。"
L["A button that flags or unflags you for PvP, showing which you are."] = "切換你的 PvP 標記的按鈕，並顯示目前狀態。"
L["A campfire in range and Camp Benefits about to run out."] = "營火在範圍內，且營地增益效果即將結束。"
L["A campfire in range and no Camp Benefits."] = "營火在範圍內，但沒有營地增益效果。"
L["A campfire is in range"] = "營火在範圍內"
L["A card behind the text, a soft dark fade, or nothing at all."] = "文字後方的卡片、柔和的暗色漸層，或什麼都沒有。"
L["A card over the pin with what it is and how far."] = "標記上方的卡片，顯示它是什麼和距離。"
L["A cast part way through, swept around the ring."] = "施法進行到一半，沿著圓環掃過。"
L["A cast someone interrupted, held for the fade time."] = "被別人打斷的施法，保留淡出時間。"
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "你的斷法冷卻中時的施法，並在斷法恢復處顯示刻度。"
L["A cast while your interrupt is ready."] = "你的斷法就緒時的施法。"
L["A cast you cannot interrupt, with its shield."] = "無法打斷的施法，附帶盾牌圖示。"
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "開啟副本追蹤後登入角色，該角色就會顯示在這裡。追蹤分身會顯示其他角色：休息經驗和耐久度，取自該角色上次登入時。"
L["A choice among its rewards: pick this one."] = "從獎勵中選擇：選這個。"
L["A command name can only use letters, numbers and underscores."] = "指令名稱只能使用字母、數字和底線。"
L["A consumable or personal buff with less time than this left counts as missing."] = "剩餘時間少於此值的消耗品或個人增益會視為缺少。"
L["A crosshair at the middle of your screen."] = "畫面中央的準心。"
L["A cup beside a healer who is drinking."] = "在正在喝水的治療者旁顯示杯子。"
L["A custom command can't reload. Type /reload."] = "自訂指令無法重新載入。請輸入 /reload。"
L["A dark or light fill and edge behind each line, or none."] = "每行後方的深色或淺色填充與邊框，或無。"
L["A dark panel behind the icons."] = "圖示後方的深色面板。"
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "在世界地圖上每個地城和團隊副本入口顯示一扇門，依照手冊列出的陣營。滑鼠指向查看等級，點擊設定導航點。"
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "在有更適合你等級的附魔可用的欄位上顯示圓點：滑鼠指向查看建議，點擊在交易頻道中詢問。"
L["A fading trail behind the cursor."] = "游標後方的淡出軌跡。"
L["A few quick steps for %s only, its own modules included."] = "只針對 %s 的幾個快速步驟，包含其自身的模組。"
L["A game that opens when a flight starts and closes when you land."] = "飛行開始時開啟、降落時關閉的遊戲。"
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "打發飛行時間的遊戲：問答或瞄準訓練。降落時關閉。"
L["A gear set called %s already exists."] = "已存在名為 %s 的裝備組合。"
L["A glow on the moving edge of the fill."] = "填充移動邊緣的光暈。"
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "橫跨艾澤拉斯的隱藏任務鏈：依序點擊世界中的每樣東西。它提供大量經驗值，最後獲得舒適的睡袋；在睡袋中休息可獲得經驗值加成。"
L["A key that opens Group Inspect."] = "開啟隊伍觀察的按鍵。"
L["A key that shows a boss's loot at your cursor."] = "在游標處顯示首領掉落物的按鍵。"
L["A key that uses this item."] = "使用此物品的按鍵。"
L["A later point needs it. "] = "之後的點數需要它。 "
L["A later step."] = "之後的步驟。"
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "你交付的每個任務一行，顯示獲得的經驗值和金錢。獎勵物品會各自顯示一行。"
L["A line for every reputation gain, from quests and kills alike."] = "每次獲得聲望一行，無論來自任務或擊殺。"
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "每次擊殺獲得的經驗值一行。任務經驗值會顯示在任務自己的那一行。"
L["A line from the pin down to a map pin's or corpse's spot."] = "從標記連到地圖標記或屍體位置的線。"
L["A line in chat with the item's link."] = "在聊天中顯示物品連結的一行。"
L["A line in their color on their player tooltip."] = "在其玩家浮動提示上以其顏色顯示一行。"
L["A line to share them with."] = "用來分享的一行字串。"
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "在 ID 下方顯示一行，說明哪些按鍵可複製（Ctrl-Shift-C：複製 ID 或 Wowhead 連結）。關閉時快捷鍵仍可使用，只是不顯示該行。"
L["A look you do not have yet|r"] = "你還沒有的外觀|r"
L["a macro made on this character"] = "在此角色上建立的巨集"
L["A macro this character does not have yet: the import makes it."] = "此角色還沒有的巨集：匯入時會建立。"
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "開啟 %s 的小地圖按鈕。/nf%s 效果相同，頂部列也可以放置它。為此電腦儲存。"
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Naowh 權重字串，或 WoWSims EP 匯出（在 WoWSims 中：Stat Weights、Copy to Current EP、Export）"
L["A Naowh weights line, or a WoWSims EP export."] = "Naowh 權重字串，或 WoWSims EP 匯出。"
L["A new session, before any experience."] = "新的階段，尚未獲得任何經驗值。"
L["A parry by your target took 40% off its swing."] = "目標的招架讓它的揮擊時間減少了 40%。"
L["A party of five, a card each."] = "五人隊伍，每人一張卡片。"
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "在浮動提示上顯示玩家分數。使用 Naowh Forever 的玩家會分享自己的分數；其他人的分數會在你滑鼠指向時從裝備讀取，需在觀察範圍內且非戰鬥中。"
L["A profile"] = "一個設定檔"
L["a quest"] = "一個任務"
L["A quest reward for the other faction; try the Auction House."] = "另一陣營的任務獎勵；試試拍賣場。"
L["A raid for %d players"] = "%d 人團隊副本"
L["A raid, a row each."] = "團隊，每人一列。"
L["A rare someone else is fighting."] = "別人正在打的稀有怪。"
L["A rare you have killed before."] = "你擊殺過的稀有怪。"
L["A rare you have not killed yet."] = "你尚未擊殺的稀有怪。"
L["A reward from the quest "] = "此任務的獎勵： "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "游標周圍的圓環，讓你在混亂的戰鬥中不會跟丟它，並沿著它顯示公共冷卻和施法進度。"
L["A round in progress."] = "進行中的回合。"
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "一排圖示，顯示缺少的食物、精煉藥劑、藥劑和卷軸增益、你自己的職業增益，以及隊伍中缺少的職業增益。僅限非戰鬥中：戰鬥中遊戲不讓插件讀取你的增益，因此圖示會維持原狀。滑鼠指向可選擇要使用的攜帶物品。在 HUD 編輯器中移動。"
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "在最新一行旁顯示即時每小時金幣，計算本次階段第一次拾取以來的金錢和物品價值。"
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "拍賣場上的掃描價格按鈕。它會讀取所有拍賣，並記下每件物品在此伺服器和陣營的最低直購價。暴雪每 15 分鐘只允許一次完整掃描。"
L["A junk icon on the bag slot of each item marked as junk."] = "在每件標記為垃圾的物品的背包欄位上顯示垃圾圖示。"
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "專注目標的第二個面板，讓你在對付另一個敵人時仍能掌握悶棍或變形術的剩餘時間。"
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "騎乘或休息時自動換上的組合，之後會換回原本的組合。"
L["A shooting game for flights: click the other faction's races as fast as you can."] = "飛行時的射擊遊戲：盡快點擊另一陣營的種族。"
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "進入和離開戰鬥時短暫閃現的文字。在 HUD 編輯器中移動。"
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "顯示下次訓練師造訪和你的金幣的小計量條，升級時可一直顯示。拖曳以移動。"
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "你坦怪時顯示隊伍中另一位坦克的小生命條：坦克職責、熊形態、防禦姿態或正義之怒。另一位坦克是擁有坦克職責或團隊主坦克指派的人。點擊以選取他。戰鬥中的變更會在戰鬥結束時套用。在 HUD 編輯器中移動。"
L["A soft glow around Naowh's arrow."] = "Naowh 箭頭周圍的柔和光暈。"
L["A soft glow beside each icon."] = "每個圖示旁的柔和光暈。"
L["A soft glow round it in your accent color."] = "以你的強調色在周圍顯示柔和光暈。"
L["A soft glow round it in your rank's color."] = "以你的階級顏色在周圍顯示柔和光暈。"
L["A soft ring pulses around each target."] = "每個目標周圍脈動的柔和光環。"
L["a sound to refresh"] = "需要刷新的音效"
L["A sound, or the Speech text read aloud, as each cast starts."] = "每次開始施法時播放音效，或朗讀語音文字。"
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "播放音效，或朗讀語音文字。文字轉語音在某些電腦上可能會卡頓，因為遊戲會等待 Windows 朗讀；音效則沒有負擔。"
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "匯入時因尚未學會而無法放置的法術，會在你學會時放入其儲存的欄位，除非你已在那裡放了其他東西。"
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "當某物品有未滿的堆疊可以合併時，卡片上會顯示堆疊按鈕。"
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "在世界地圖上為每隻你尚未擊殺的稀有怪標示星號，位於其最可能出現的地點。滑鼠指向查看稀有怪及其掉落、其他出現地點和巡邏路線；點擊設定導航點，右鍵點擊則保持顯示其地點和路線。"
L["A string to share it with."] = "用來分享的字串。"
L["A supporter"] = "贊助者"
L["A team member"] = "團隊成員"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "計量條上的文字：在預覽上點擊以更改。每種文字只會顯示在計量條上的一個位置：選擇已在其他位置顯示的文字會將它移過來。"
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "在計量條上斷法冷卻結束的位置顯示刻度。就緒時隱藏。"
L["A title bar naming the mob the threat is on."] = "標題列，顯示威脅值所在的怪物名稱。"
L["A trained spell drops into its saved slot."] = "訓練的法術會放入其儲存的欄位。"
L["a vendor sells the formula"] = "商人販售此配方"
L["A warning when a rare is near"] = "稀有怪接近時的警告"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "稀有怪接近你時發出警告：當其名條出現、你滑鼠指向或選取它時。附有頭像的卡片：右鍵點擊關閉，其標記可設定前往稀有怪的導航點。在 HUD 編輯器中移動。"
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "獵人或術士沒有召喚寵物時發出警告。犧牲了惡魔的術士則不提醒。在 HUD 編輯器中移動。"
L["A word of your own on the icon."] = "圖示上顯示你自訂的文字。"
L["A world drop from %d kinds of mob"] = "來自 %d 種怪物的世界掉落"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "營火和飛行時的魔獸問答，或隨時輸入 /naowh quiz。"
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "在世界地圖上每個有可接且仍提供經驗值任務的任務給予者處顯示黃色 !。滑鼠指向查看任務；點擊設定導航點。"
L["A zone older than this is no longer shown, since the player has likely moved on."] = "超過此時間的區域不再顯示，因為該玩家可能已經離開。"
L["Abandon %s?"] = "要放棄 %s 嗎？"
L["Abilities"] = "技能"
L["about "] = "約 "
L["about %d:%02d"] = "約 %d:%02d"
L["About %s at your last scan%s%s"] = "你上次掃描時約 %s%s%s"
L["About %s spent"] = "約花費 %s"
L["About a minute."] = "約一分鐘。"
L["Above"] = "上方"
L["Acc."] = "準確"
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "強調色：缺少職業祝福。較淺：即將結束。較深：只有擁有自己祝福的玩家。"
L["Accept Quests"] = "接受任務"
L["Accept Shared Dungeon Quests"] = "接受分享的地城任務"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "任務內容一開啟就接受。使用修飾鍵可先閱讀。"
L["Accepts dungeon quests your group shares with you straight away."] = "立即接受隊伍分享給你的地城任務。"
L["Accepts shared quests"] = "接受分享的任務"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "接受畫面上的彈出視窗：召喚、復活、隊伍邀請。"
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "為你接受、交付和分享任務，並記住你為某任務選定的獎勵。修飾鍵會略過或觸發它們，依「修飾鍵作用」的設定。"
L["Account"] = "帳號"
L["Account "] = "帳號 "
L["Account macros"] = "帳號巨集"
L["Account this hour: %d of %d"] = "本小時帳號：%d/%d"
L["Accuracy"] = "準確度"
L["Action Bars is switched off."] = "快捷列已關閉。"
L["Action Bars' own window, with your class's saved sets."] = "快捷列自己的視窗，包含你職業的已儲存組合。"
L["Active"] = "啟用中"
L["Activity Bar"] = "活動條"
L["Activity Bar Color"] = "活動條顏色"
L["Activity Bar Height"] = "活動條高度"
L["Add %d item to your junk list: %s%s?"] = "要將 %d 件物品加入你的垃圾清單嗎：%s%s？"
L["Add %d items to your junk list: %s%s?"] = "要將 %d 件物品加入你的垃圾清單嗎：%s%s？"
L["Add %d macro as character macros?%s"] = "要將 %d 個巨集加入為角色巨集嗎？%s"
L["Add %d macros as character macros?%s"] = "要將 %d 個巨集加入為角色巨集嗎？%s"
L["Add %s"] = "新增 %s"
L["Add %s (%d items) as a new BiS list?"] = "要將 %s（%d 件物品）加入為新的最佳裝備清單嗎？"
L["Add %s to the Consumable Bar?"] = "要將 %s 加入消耗品列嗎？"
L["Add a backup pick"] = "新增備用選擇"
L["Add a Button"] = "新增按鈕"
L["Add a stat"] = "新增屬性"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "新增物品 ID，或匯入清單。食物會計算任何進食充分增益，其他物品則計算其自身增益；只有當物品提供不同增益時才需加入增益法術 ID。不會自動加入任何東西。滑鼠指向提醒可從背包選擇已設定的物品。提醒在戰鬥中暫停；物品選單在非戰鬥時可用。顯示的時機和位置在 光環增益 > 設定 中。"
L["Add consumables, put them in order, and set each one up."] = "新增消耗品、排序，並逐一設定。"
L["Add Items"] = "新增物品"
L["Add Latency"] = "加入延遲"
L["Add macros someone shared with you."] = "加入別人分享給你的巨集。"
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "新增或移除你的指令，逐一開關，或恢復預設值。"
L["Add Slash Command"] = "新增斜線指令"
L["Add the %s build %s (%d points)?"] = "要加入 %s 的配置 %s（%d 點）嗎？"
L["Add the consumables to watch in the AuraBuffs window."] = "在光環增益視窗中新增要監看的消耗品。"
L["Add Themes to RestedXP"] = "將主題加入 RestedXP"
L["Add to BiS List"] = "加入最佳裝備清單"
L["Add to Shopping List"] = "加入購物清單"
L["Add to the Left Side"] = "加入左側"
L["Add to the Right Side"] = "加入右側"
L["Add your consumables, put them in order, set each one up."] = "新增你的消耗品、排序，並逐一設定。"
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "在背包巨集中加入你自己的行。無論背包中有什麼，它們都會保留在物品之後。"
L["Added %d consumable to the Consumable Bar."] = "已將 %d 個消耗品加入消耗品列。"
L["Added %d consumables to the Consumable Bar."] = "已將 %d 個消耗品加入消耗品列。"
L["Added %d consumables; %d were already listed or past the %d limit."] = "已新增 %d 個消耗品；%d 個已在清單中或超過 %d 個上限。"
L["Added %d of %d: %s."] = "已新增 %d/%d：%s。"
L["Added %d."] = "已新增 %d 個。"
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "已將 %s 加入此角色。從遊戲的巨集視窗（/macro）將它拖到快捷列。"
L["Added %s to your BiS %s as #%d."] = "已將 %s 加入你的最佳裝備%s，排第 %d。"
L["Added %s to your BiS %s."] = "已將 %s 加入你的最佳裝備%s。"
L["Added next to your Library, never over it"] = "加在你的收藏庫旁，不會覆蓋"
L["Added next to your own lists, never over them"] = "加在你自己的清單旁，不會覆蓋"
L["Added next to your saved builds"] = "加在你已儲存的配置旁"
L["Adding Items"] = "新增物品中"
L["Addon Font"] = "插件字型"
L["Addon List"] = "插件清單"
L["Addon Memory"] = "插件記憶體"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "在配方材料下方加入「- [1] + 加入清單」：拍賣場購買會為該次數製作所購買的材料會加入購物清單，隨處可用。在拍賣場時清單會顯示在旁邊：查詢價格會逐一查價，並在價格遠高於你上次掃描時以紅色警告，接著全部購買會逐一處理清單中的材料，每項都在你確認最終價格後才購買。可以用零件更便宜製作的材料（例如用礦石製作金屬條）則會改買其零件。"
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "在選定配方的材料中加入背包欄，顯示你攜帶的數量。"
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "在選定配方的材料中加入銀行欄，顯示你銀行中的數量。"
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "在彈出視窗中加入按鈕，將快捷列上所有較低等級的法術換成你所知的最高等級。鍵盤和控制器快捷列會放在相同欄位。在彈出視窗中右鍵點擊法術可保留其較低等級，用於降階施法。等級替換只在非戰鬥時進行。"
L["Adds a Land button to come down at the next stop on the way."] = "加入降落按鈕，可在途中的下一站降落。"
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "加入一行，標出附魔缺少或與你用「擷取目前附魔」記錄的不同的欄位。滑鼠指向查看詳情。"
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "在法力法術的浮動提示中加入每點法力和每秒的治療或傷害。"
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "在每個配方旁加入第二個橘色數字：購買商人販售的材料（例如弱效助熔劑或粗線）後可製作的數量。配方材料會顯示每種需要購買的數量。"
L["Adds how long the visit lasted."] = "加入造訪持續的時間。"
L["Adds target and focus switching to the meter's title bar."] = "在監控的標題列加入目標和專注目標切換。"
L["Adds the average experience here."] = "加入此處的平均經驗值。"
L["Adds the coins looted."] = "加入拾取的金錢。"
L["Adds the consumables in your bags that are not on the bar yet."] = "加入背包中尚未放上列的消耗品。"
L["Adds the deaths."] = "加入死亡次數。"
L["Adds the experience gained."] = "加入獲得的經驗值。"
L["Adds the materials for one more craft."] = "加入再製作一次所需的材料。"
L["Adds the Naowh themes to RestedXP's theme list."] = "將 Naowh 主題加入 RestedXP 的主題清單。"
L["Adds the reputation gained."] = "加入獲得的聲望。"
L["Adds the visits at this level."] = "加入此等級的造訪次數。"
L["Adds the visits until you level."] = "加入升級前所需的造訪次數。"
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "加入你的治療加成或法術傷害；關閉時顯示法術的基礎數值。"
L["Advanced"] = "進階"
L["Advanced (CMAA2)"] = "進階（CMAA2）"
L["Advanced Combat Logging"] = "進階戰鬥紀錄"
L["after "] = "之後 "
L["After each fight longer than 15 seconds, how long you spent neither casting nor on the global cooldown, in chat."] = "每場超過 15 秒的戰鬥後，在聊天中顯示你既未施法也不在公共冷卻中的時間。"
L["after the 5% cut"] = "扣除 5% 手續費後"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "拜訪訓練師後，會有小視窗列出你剛學會的技能。從書籍或任務學會的技能會在學會後稍等一下才顯示。從視窗中將它拖到快捷列上。"
L["Aggro Line"] = "仇恨線"
L["Aggro Line Color"] = "仇恨線顏色"
