L["Also a grey ! for quests you can still pick up that no longer give experience."] = "也為仍可接但不再提供經驗值的任務顯示灰色 !。"
L["Also a grey star on the map for the rares you have killed."] = "也在地圖上為你已擊殺的稀有怪顯示灰色星號。"
L["Also hidden for a few seconds after you dismount, while the pet comes back."] = "下坐騎後數秒內寵物歸來期間也會隱藏。"
L["Also Import"] = "同時匯入"
L["Also in use on"] = "也用於"
L["Also keeps your last whispers and group chat lines with each player."] = "也保留你與每位玩家最近的密語和隊伍聊天內容。"
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "同時在導航點上開啟世界地圖，讓你看到它的位置。僅限非戰鬥中。"
L["Also prints the summary when you leave a raid."] = "離開團隊時也顯示摘要。"
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "在副本內也提醒。預設關閉：很少副本有草藥或礦。"
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "同時在清單中每個配方的右側以綠色或紅色顯示利潤。利潤未知的配方不顯示。"
L["Also thanks players in your party or raid."] = "也感謝你隊伍或團隊中的玩家。"
L["Also used inside dungeons and raids."] = "在地城和團隊副本中也會使用。"
L["Also warns about rares you have killed before."] = "也對你擊殺過的稀有怪發出警告。"
L["Also warns while your pet is set to passive."] = "寵物設為被動時也發出警告。"
L["Also warns while your pet's health is under the threshold, in combat too."] = "寵物生命值低於門檻時也發出警告，戰鬥中也是。"
L["Also worth a look"] = "也值得一看"
L["Alt"] = "Alt"
