L["Buys from this merchant, in one click, every checked reagent it sells, for that many crafts, whatever is already in your bags. Set the number with the - and + beside it; uncheck a reagent to leave it out."] = "一鍵向此商人購買所有已勾選且其販售的材料，數量為該製作次數所需，不論背包中已有多少。用旁邊的 - 和 + 設定數量；取消勾選材料即可略過。"
