L["Buys what your bags lack of this merchant's reagents for %d crafts, the orange number next to the recipe, so Create All can make them all. Uncheck a reagent to leave it out."] = "購買背包中不足的此商人材料，足夠製作 %d 次（配方旁的橘色數字），讓全部製作可以一次完成。取消勾選材料即可略過。"
