L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "拖曳右邊緣調整寬度。滾輪：文字大小（Shift：高度）。點擊加成或時間以顯示或隱藏。右鍵點擊查看更多。"
