L["Each camp feature's own icon before its bonus."] = "每個營地設施的圖示顯示在其加成前。"
L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "每個職業的名稱或圖示，顯示在其按鈕下方，或計量條垂直時顯示在旁邊。"
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "副本追蹤開啟時的每次地城或團隊副本造訪：你在裡面待了多久、拾取的金錢和獲得的經驗值。獲得的聲望列在該次造訪下方。在一小時內、重置前回到同一個隊伍會延續該次造訪，在外面的時間不計。其他角色的資料會保留，開啟追蹤分身時顯示在這裡。修理和賣給商人的收入不計入。較舊的造訪會從清單末端移除。"
L["Each line fades out after %ss."] = "每行在 %s 秒後淡出。"
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "每個都是帳號巨集。放上快捷列一次就會自動保持最新：拾取更好的藥水、造出新的食物或撿到繃帶，巨集就會改寫為使用你攜帶的最佳物品。\n\n遊戲不允許巨集在戰鬥中變更，因此戰鬥中的變更會等到戰鬥結束。"
L["Each point of the trail in a color of its own."] = "軌跡的每個點各有自己的顏色。"
L["Each slot's item level, in its icon's corner."] = "每個欄位的物品等級，顯示在其圖示角落。"
L["Each visit, with its time, coins, and experience."] = "每次造訪，含時間、金錢和經驗值。"
