L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "聖騎士專用，你隊伍中每個職業一個按鈕。左鍵點擊會為該職業中下一位需要的成員施放祝福，缺少者優先，略過死亡或超出範圍的人。右鍵點擊職業可選擇其祝福或開啟其玩家清單。在 HUD 編輯器中移動。預覽可以編輯它：右鍵點擊職業選擇祝福，點擊光環選擇光環，滾輪調整大小，Shift-滾輪調整間距，拖曳光環後的間隙，x 隱藏按鈕，+ 恢復按鈕。"
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Skyborne 角色專用：在世界地圖上標出地脈（聯盟，用於解讀地脈）或元素匯聚（部落，用於天之視覺）。遊戲不會標示它們：插件知道玩家已發現的位置，並會儲存你施放種族技能找到的每個新位置。其他種族看不到這些標記。"
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "你的職業專用：在新角色 1 級且尚無經驗值時匯入此組合一次。"
L["For your level"] = "適合你的等級"
