L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "掃描拍賣場（掃描價格）後，選定的配方會顯示購買材料的成本、物品的售價，以及扣除 5% 拍賣場手續費後的利潤。每種材料以最便宜的價格計算：看過商人販售後使用商人價格，否則使用上次掃描的最低直購價。取消勾選你已有的材料即可在所有使用它的配方中不計入成本。滑鼠指向各行查看明細。"
L["One addon"] = "一個插件"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "每把武器一條計量條，以遊戲本身的揮擊事件計時，因此招架加速、揮擊重置和加速永遠正確。在 HUD 編輯器中移動。"
L["One Fewer"] = "少一個"
L["One item per click: the game needs a click for every disenchant."] = "每次點擊一件物品：遊戲每次分解都需要點擊。"
L["One More"] = "多一個"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "代表角色裝備的單一數字，以物品等級為尺度：26.4 代表裝備相當於一整套 26 級史詩。你自己的分數一直顯示在最佳裝備清單的角色紙娃娃上。"
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "每行一則密語，隨機挑選；會自動填入 {buff} 和 {name}。"
