L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "在此視窗中開啟其他玩家的專業連結，向他們訂製物品。選擇配方，設定製作次數，勾選你自備的材料（或輸入數量），然後加入順序。右側的訂單有每次製作的建議小費，你可以更改；詢問會為每次製作傳送一則訊息給製作者，包含數量、你的材料和小費：對方在你的隊伍中時用隊伍聊天，否則用密語。價格和小費需要拍賣場掃描。"
L["Opens its settings and leaves the HUD Editor."] = "開啟其設定並離開 HUD 編輯器。"
L["Opens the Aim Trainer now, out of combat."] = "立即開啟瞄準訓練，限非戰鬥時。"
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "開啟光環增益視窗，在其中依物品 ID 和增益法術 ID 新增每件物品。"
L["Opens the Consumable Bar's settings."] = "開啟消耗品列的設定。"
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "在範例法術上開啟複製卡片。選取 ID 或連結，然後按 Ctrl+C。"
L["Opens the Dungeon Journal's Quest Tracker settings."] = "開啟地城導覽手冊的任務追蹤設定。"
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "開啟 HUD 編輯器：點擊另一個 Naowh Forever 元件，讓計量條隨之移動。"
L["Opens the Library Books tracker's settings."] = "開啟圖書館書籍追蹤器的設定。"
