L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "每次你的生命值低於門檻時播放一次。如果遊戲在戰鬥中對插件隱藏你的生命值，則只在非戰鬥時播放。"
