L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "在你的專注目標上放置團隊標記。對同一個專注目標再次按下巨集會清除標記。"
L["Puts back every setting this page has changed, to the value you had before."] = "將此頁面變更過的所有設定恢復為你之前的值。"
L["Puts back everything changed since the HUD Editor opened."] = "還原 HUD 編輯器開啟後的所有變更。"
L["Puts back the last change. Ctrl + Z."] = "還原上一次變更。Ctrl + Z。"
L["Puts both back where the game shows them."] = "將兩者放回遊戲顯示的位置。"
L["Puts every weight of this spec back to the defaults. Asks first."] = "將此專精的所有權重恢復為預設值。會先詢問。"
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "將比你低 10 級以上的食物、飲料和藥水（以時鐘標記）排在最前面。"
L["Puts the bar back on the screen."] = "將計量條放回畫面上。"
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "將列上的按鈕恢復原狀：地城導覽手冊和探索在左側，最佳裝備清單和訓練規劃在右側。"
L["Puts the card back above the middle of the screen, where it starts."] = "將卡片放回畫面中央上方的起始位置。"
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "將最便宜的物品放在列的最遠端，而不是緊鄰其錨點。"
L["Puts the cheapest item on your cursor, to drop or sell."] = "將最便宜的物品放到游標上，以便丟棄或賣出。"
L["Puts the count just past the icon's edge."] = "將數量放在圖示邊緣外側。"
L["Puts the key just past the icon's edge."] = "將按鍵放在圖示邊緣外側。"
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "將該製作次數所需的材料放入你的購物清單：所有已勾選且商人不販售的材料，不論背包中已有多少。取消勾選材料即可略過。在拍賣場時清單會顯示在旁邊，可查詢價格並全部購買。"
L["Puts the popup back where it first showed."] = "將彈出視窗放回第一次顯示的位置。"
L["Puts the quiz back where it first opened."] = "將問答放回第一次開啟的位置。"
L["Puts the text just past the icon's edge."] = "將文字放在圖示邊緣外側。"
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "將此配方加入右側的訂單，包含製作次數和你自備的材料。加入後在此處的變更也會更改訂單。每張訂單最多 %d 個配方。"
L["Puts this set on. In combat, it goes on when the fight ends."] = "穿上此組合。戰鬥中則在戰鬥結束時穿上。"
