L["Shown: click to hide it."] = "已顯示：點擊以隱藏。"
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "你在地城內時，在世界地圖旁顯示該地城的首領和掉落。"
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "你的生命值低於門檻時立即顯示治療物品的圖示，戰鬥中也是：由遊戲自行顯示和隱藏。在 HUD 編輯器中移動。"
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "顯示範例法術的浮動提示，以你的設定呈現該行。"
L["Shows a zone's level range when you hover it on the world map."] = "在世界地圖上滑鼠指向區域時顯示其等級範圍。"
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "你學會尋找草藥、尋找礦物或尋找魚類但都未追蹤時，在畫面上顯示圖示。點擊開始追蹤：左鍵點擊第一個，右鍵點擊第二個，中鍵點擊第三個。滑鼠指向查看各是哪個。戰鬥中隱藏。在 HUD 編輯器中移動。"
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "顯示每個睡袋步驟，以及如何前往下一步和導航點。"
L["Shows every bonus again; click one on the preview to hide it."] = "再次顯示所有加成；在預覽上點擊一個以隱藏。"
L["Shows how many of each you carry."] = "顯示你攜帶的每種數量。"
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "顯示你領先或落後你的其他角色，並依此為過去的等級上色。"
L["Shows it again a little before its effect runs out."] = "在其效果結束前稍早再次顯示。"
L["Shows only part of the raid."] = "只顯示團隊的一部分。"
L["Shows or hides the list of every element."] = "顯示或隱藏所有元件的清單。"
L["Shows the factions earned where you are beside the world map."] = "在世界地圖旁顯示你所在位置可獲得的陣營聲望。"
L["Shows the key that uses each button."] = "顯示使用每個按鈕的按鍵。"
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "在監控於畫面上的位置以範例計量條顯示十秒。僅限非戰鬥時。"
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "在另一位坦克的生命條旁顯示其減益效果，戰鬥中也是：坦克殺手層數、首領減益和任何你可以驅散的效果。"
L["Shows the parts of the world map you have not explored yet, darkened."] = "以暗色顯示世界地圖上你尚未探索的部分。"
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "只在背包滿到此程度時顯示此列。0 表示一直顯示。"
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "在你的地圖上顯示仍待完成的睡袋步驟；點擊一個設定導航點。"
L["Shows the warning with its sound, about your target if you can attack it."] = "顯示警告及其音效，若你可以攻擊目標則針對你的目標。"
L["Shows this bonus on the bar: %s."] = "在計量條上顯示此加成：%s。"
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "在你的目標追蹤器中顯示此配方的材料，以及你每種擁有的數量。"
L["Shows this visit's time, coins, and experience."] = "顯示本次造訪的時間、金錢和經驗值。"
L["Shows up once you take the talent"] = "點選天賦後才會顯示"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "顯示誰是 Naowh、開發者、管理員以及我們的傳說和史詩贊助者：聊天中名稱旁的徽章、浮動提示上的一行，以及（如果你想要）他們加入你的隊伍時的橫幅。"
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "向使用 Naowh Forever 觀察你的玩家顯示你的最佳裝備星號。"
L["Shows your note and tag on a player's tooltip."] = "在玩家的浮動提示上顯示你的筆記和標籤。"
L["Shows your other characters' visits."] = "顯示你其他角色的造訪。"
