L["The extra gap between your aura and Righteous Fury and the class buttons."] = "你的光環和正義之怒與職業按鈕之間的額外間距。"
L["The fastest way to any waypoint."] = "前往任何導航點的最快路線。"
L["The first %d of %d; type more to narrow it down."] = "前 %d 個，共 %d 個；輸入更多字以縮小範圍。"
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "有人第一次說話時，以隱藏的插件密語向其 Naowh Forever 詢問所在區域。沒有安裝的玩家不會看到詢問。"
L["The flight time to each destination when you hover it on the flight master's map."] = "在飛行管理員的地圖上滑鼠指向每個目的地時顯示飛行時間。"
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "傷害和治療數字的字型，顯示在敵人和你的角色上方。關閉時保持遊戲本身的字型。"
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "遊戲其他部分的字型：選單、聊天、浮動提示和名稱。關閉時保持遊戲本身的字型。"
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "此插件的視窗和 HUD 的字型。功能上的字型設定會使用它，除非另有選擇。為此電腦儲存。|n|n/reload 後生效。"
L["The FPS / MS readout and the online counts on the buttons."] = "FPS / MS 讀數和按鈕上的線上人數。"
L["The FPS / MS readout stays up."] = "FPS / MS 讀數保持顯示。"
L["The game does not name this fight yet: its kills count once the raid opens."] = "遊戲尚未命名此戰鬥：團隊副本開放後才會計算其擊殺。"
L["The game has no PvP rank for you yet. It shows once the season has started."] = "遊戲尚未給你 PvP 階級。賽季開始後才會顯示。"
L["The game has no route for %s, and its quest giver's spot is not known."] = "遊戲沒有前往 %s 的路線，且其任務給予者的位置未知。"
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "遊戲目前不傳遞插件訊息（首領戰中）：戰鬥後再詢問。"
L["The game lists no rank rewards for this season yet."] = "遊戲尚未列出本賽季的階級獎勵。"
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "遊戲不允許分解此物品（技能太低？）。重新載入前將略過。"
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "先播放遊戲本身的警示音效，然後是插件的。選擇時會播放試聽。"
L["The game's own look, in gold and bronze."] = "遊戲本身的外觀，金色與青銅色。"
L["The gap between the two."] = "兩者之間的間距。"
L["The gap between two buttons."] = "兩個按鈕之間的間距。"
L["The Gear Sets window, with every set and what you can do with it."] = "裝備組合視窗，包含每個組合以及你可以對它做的事。"
L["The group can be disbanded once the fight is over."] = "戰鬥結束後才能解散隊伍。"
L["The group's paladins and the blessing each gives every class."] = "隊伍中的聖騎士，以及每位給各職業的祝福。"
L["The guild name under a player's name."] = "玩家名稱下方的公會名稱。"
L["The highest rank this season"] = "本賽季最高階級"
L["The icon grows and shrinks with it."] = "圖示會隨之放大縮小。"
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "最佳裝備清單風格的觀察視窗，含其分數、裝備檢查、天賦和歷史紀錄。"
L["The item's cooldown sweeps over its icon."] = "物品的冷卻會掃過其圖示。"
L["The item's quality"] = "物品的品質"
L["The item, your star and what happened, on screen for a while."] = "物品、你的星號和發生的事，在畫面上顯示一段時間。"
L["The items the Buffs & Consumables reminders watch."] = "增益與消耗品提醒監看的物品。"
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "世界地圖旁的手冊：地城中的首領和掉落，野外的陣營聲望。"
L["The Journal's own window."] = "手冊自己的視窗。"
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "改變接受任務、交付任務、從 NPC 選擇任務和分享行為的按鍵。"
L["The key that changes Auto Gossip for that NPC."] = "改變該 NPC 自動對話行為的按鍵。"
L["The key that opens the BiS List."] = "開啟最佳裝備清單的按鍵。"
L["The key that opens the Journal."] = "開啟手冊的按鍵。"
L["The key that opens the Quest List window."] = "開啟任務清單視窗的按鍵。"
L["The last %ds, scrolling %s%s"] = "最近 %d 秒，%s%s 捲動"
L["The last fight's time stays on screen until the next one starts."] = "上一場戰鬥的時間會保持在畫面上，直到下一場開始。"
L["The last part of each melee swing, shaded."] = "每次近戰揮擊的最後一段，以陰影顯示。"
L["the last profile cannot be deleted"] = "無法刪除最後一個設定檔"
L["The last profile cannot be deleted."] = "無法刪除最後一個設定檔。"
L["The latest %d kills. First counted: %s."] = "最近 %d 次擊殺。首次計算：%s。"
L["The latest %d. First counted: %s."] = "最近 %d 次。首次計算：%s。"
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "每個隊伍搜尋器清單上隊長的區域，滑鼠指向時顯示每位成員的區域。"
L["The level you are on as it runs, then completed levels, newest first."] = "進行中的等級，然後是已完成的等級，最新的在前。"
L["The line round the bar."] = "計量條周圍的線。"
L["The list this character uses."] = "此角色使用的清單。"
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "增益可顯示的最長持續時間；更長的如秘法智力會保持隱藏。"
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "插件在非戰鬥時為你撰寫並保持最新的巨集。在這裡開啟，或從 Naowh 鍛造所的智慧巨集將它拖到快捷列。"
L["The macros you saved to the Forge's Library."] = "你存到鍛造所收藏庫的巨集。"
L["The Man. The King."] = "傳奇人物。王者。"
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "地圖視窗、世界地圖旁的手冊和游標處首領掉落。"
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "遊戲本身角色面板（或 EllesmereUI 的）上的標記，不使用 Naowh 角色面板時。開啟角色面板時，其欄位已經有標記。"
L["The Middle-click line."] = "中鍵點擊那行。"
L["The most recent completed levels."] = "最近完成的等級。"
L["the name is empty"] = "名稱是空的"
L["The name on it, and the community it is made for."] = "上面的名稱，以及它為哪個社群製作。"
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "小地圖上的 Naowh Forever 按鈕。插件收納區項目和 /naowh 都可以開啟此視窗。"
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "聊天中 Naowh、開發者、管理員以及我們的傳說和史詩贊助者名稱旁的 Naowh Forever N 標誌。"
L["The newest line stays at the anchor; older lines stack in this direction."] = "最新的行保持在錨點處；較舊的行往此方向堆疊。"
L["The next one frees in "] = "下一個名額釋出於 "
L["the next rank of %s (cap %d)"] = "%s 的下一等級（上限 %d）"
L["The number on each icon counts your bank as well as your bags."] = "每個圖示上的數字會同時計算你的銀行和背包。"
L["The order the points are taken in"] = "點數的分配順序"
L["the pattern"] = "圖樣"
L["The people and projects behind Naowh Forever."] = "Naowh Forever 背後的人和專案。"
L["The picked boss's loot and abilities, under the map."] = "選定首領的掉落和技能，顯示在地圖下方。"
L["The planner's own window, and a mini bar to leave up while you level."] = "規劃自己的視窗，以及升級時可一直顯示的迷你列。"
L["The player list opens after combat."] = "玩家清單會在戰鬥後開啟。"
L["The player's guild rank beside their guild name."] = "在公會名稱旁顯示玩家的公會階級。"
L["The point of the bar that attaches."] = "計量條要附加的錨點。"
L["The point of the frame it attaches to."] = "要附加到的框架錨點。"
L["The purchase failed."] = "購買失敗。"
L["The purchase failed; the price may have changed."] = "購買失敗；價格可能已變動。"
L["The purchase failed; the price may have changed.|r"] = "購買失敗；價格可能已變動。|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "任務追蹤器，以及與隊伍分享地城任務。"
L["The quests that reward a pick you do not have yet."] = "獎勵你尚未擁有的選擇的任務。"
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "坐在營火旁時開啟問答，站起來時關閉。"
L["The raid marker Mark Focus puts on your focus."] = "標記專注目標放在你專注目標上的團隊標記。"
L["the rank before"] = "前一等級"
L["The ready ring shows with GCD Sweep on."] = "開啟公共冷卻掃描時顯示就緒圓環。"
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "你已知法術使用的材料，例如魔粉、蠟燭、種子、王者印記和閃光粉，依你所知的最高等級配對。"
L["The red time left blinks, to catch your eye."] = "紅色的剩餘時間會閃爍，以吸引你注意。"
L["The same required-level filter applies to every stack, not each item separately."] = "相同的需求等級過濾會套用到每一疊，而不是每件物品分開計算。"
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "與角色資訊相同的組合：在裝備組合視窗中裝備、儲存、重新命名或刪除。"
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "攜帶王者印記時，對共用同一祝福的職業以強效祝福做同樣的事。"
L["The seconds left when the time turns red; it turns yellow at twice that."] = "時間變紅時的剩餘秒數；兩倍時間時變黃。"
L["The serializer libraries are missing from this build."] = "此版本缺少序列化函式庫。"
L["The shape of Naowh's arrow."] = "Naowh 箭頭的形狀。"
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "建議小費在補償製作者自備材料之外，額外加上物品售價的此比例。至少 1 銀，除非設為 0。"
L["The shortest time between two thanks to the same player."] = "對同一位玩家兩次感謝之間的最短時間。"
L["The Slot"] = "欄位"
L["The slot it is for."] = "它適用的欄位。"
L["The slots and stats only"] = "僅欄位和屬性"
L["The space between Naowh's arrow and the text under it."] = "Naowh 箭頭與其下方文字之間的間距。"
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "你的裝備依此專精衡量。自動會依照你的天賦：點數最多的天賦樹（德魯伊的野性戰鬥以傷害衡量；熊形態請選擇野性坦克）。"
L["The spot ahead of you, 312 yards away."] = "前方的地點，距離 312 碼。"
L["The spot off to your right."] = "你右側的地點。"
L["The stat weights each spec starts with."] = "每個專精的初始屬性權重。"
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "潛行中時顯示潛行中文字，未潛行時顯示提醒。"
L["The step and distance text under RestedXP's waypoint arrow."] = "RestedXP 導航箭頭下方的步驟和距離文字。"
L["The string is damaged: copy it again in full."] = "字串已損壞：請重新完整複製。"
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "建議小費會補償製作者的材料，再加上物品售價的 %d%%（若配方不產出物品，則為所有材料的價值），四捨五入，至少 1 銀。可在右側的訂單清單中設定你自己的小費。在專業設定中更改比例。"
L["The swing timer needs WoW: Forever's own swing event."] = "揮擊計時器需要 WoW: Forever 本身的揮擊事件。"
L["The tag in the speaker's class color. Off, it is grey."] = "標籤以說話者的職業顏色顯示。關閉時為灰色。"
L["the talent above it"] = "其上方的天賦"
L["The talent builds you saved in the Training Planner."] = "你在訓練規劃中儲存的天賦配置。"
L["The Team"] = "團隊"
L["The text in the theme's accent color instead of gold."] = "文字使用主題的強調色，而不是金色。"
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "RestedXP 使用的主題：其本身的，或 Naowh 主題之一。"
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "兩側之間的時間。點擊開啟行事曆（控制器不可用）。"
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "剩餘時間會變黃，接近結束時變紅，讓你看到群體控制即將解除。"
L["The time left, turning yellow, then red, as the camp runs down."] = "剩餘時間隨營地減少變黃，再變紅。"
L["The tint on every button's icon: Naowh's own and any addon's."] = "每個按鈕圖示的色調：Naowh 本身的和任何插件的。"
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "訓練規劃在你升級時的協助：升級時有法術可訓練會顯示通知，並在你的職業訓練師旁顯示面板。"
L["The unit frame the bar is attached to, or UIParent for the screen."] = "計量條附加的單位框架，或用 UIParent 表示畫面。"
L["The weights"] = "權重"
L["The weights for %s."] = "%s 的權重。"
L["The window's border fades with it."] = "視窗邊框會一起淡出。"
L["The word itself."] = "文字本身。"
L["The XP of completed quests, and their text."] = "已完成任務的經驗值及其文字。"
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "進行中任務的經驗值，以淡化區段顯示在已完成任務之後。"
L["The XP of quests still in progress. By default the completed quests color, faded."] = "進行中任務的經驗值。預設為已完成任務的顏色淡化。"
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "在聊天頻道、公會聊天或密語中說話者的訊息前顯示其區域。遊戲從不告知陌生人在哪裡，因此玩家要在隊伍搜尋器、你的公會、好友或隊伍中，出現在 /who 結果，或由其自己的 Naowh Forever 回覆後才會被標記。其第一則訊息可能沒有標記。"
L["Their BiS"] = "他們的最佳裝備"
L["THEIR GEAR"] = "他們的裝備"
L["Their gear, talents and history"] = "他們的裝備、天賦和歷史紀錄"
L["their materials + %d%%"] = "他們的材料 + %d%%"
L["Their materials:"] = "他們的材料："
L["Their Naowh Score at the top of the panel, with yours under it."] = "面板頂部顯示他們的 Naowh 分數，你的在其下方。"
L["Their supporter badge in the window's corner, if they have one."] = "若他們有贊助者徽章，顯示在視窗角落。"
