L["Them"] = "他們"
L["them all."] = "全部。"
L["Theme"] = "主題"
L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "插件視窗和 HUD 框架的主題預設，另有自訂選項可設定你自己的顏色。如果文字難以閱讀，請選擇 Naowh（預設）。為此電腦儲存。|n|n/reload 後生效。"
L["then"] = "然後"
L["then "] = "然後 "
L["There are no consumables to export yet."] = "尚無可匯出的消耗品。"
L["There is already a bar set called %s."] = "已有名為 %s 的快捷列組合。"
