L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "每項屬性對你專精的價值：提升百分比和附魔都由此而來。可自行設定。"
L["What Happened"] = "發生了什麼"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "開啟商人時會發生什麼。無論補貨提醒是否開啟，兩者都可運作。"
L["What It Lists"] = "列出的內容"
L["What it lists"] = "列出的內容"
L["What it puts on you: a buff, or an enchant on a weapon."] = "它給你的效果：增益，或武器上的附魔。"
L["What it says while you are in stealth."] = "潛行中時顯示的內容。"
L["What it says while you are out of stealth."] = "未潛行時顯示的內容。"
L["What it shows as you enter combat."] = "進入戰鬥時顯示的內容。"
L["What it shows as you leave combat."] = "離開戰鬥時顯示的內容。"
L["What Lines Show"] = "各行顯示的內容"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Naowh 的專業視窗為每個配方加入的內容：你尚未學會的配方、你的下一等級，以及你擁有的每種材料數量。"
L["What opens when a flight starts; Off hides the Games button."] = "飛行開始時開啟什麼；關閉會隱藏遊戲按鈕。"
L["What Rows Show"] = "各列顯示的內容"
L["What shows while you know a find but track none."] = "你會尋找技能但都未追蹤時顯示的內容。"
L["What the copy card has selected when it opens."] = "複製卡片開啟時已選取的內容。"
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "手冊在首領上列出的內容。與其標題列上過濾圖示的開關相同。"
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "該疊物品在拍賣場的價值，取自你上次掃描價格或 TradeSkillMaster。"
L["What the whole stack sells for at a vendor, and each item's price."] = "整疊物品賣給商人的價格，以及每件的價格。"
L["What to train at each level, and its cost."] = "每個等級要訓練什麼，以及其費用。"
L["What you can train now and what each level brings."] = "你現在可以訓練什麼，以及每個等級帶來什麼。"
L["What you can train now, what each level brings and what it costs."] = "你現在可以訓練什麼、每個等級帶來什麼，以及費用。"
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "你為此製作支付給製作者的金額，隨密語送出。預設填入建議小費；可自行輸入如 2g 50s、75s 或 2.5（金）。清空即可恢復建議值。"
L["What you wear that takes a better enchant for your level."] = "你身上可以換更適合你等級附魔的裝備。"
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "你的目標在戰鬥中的狀態：其短效增益和身上的群體控制。"
L["Wheel"] = "滾輪"
L["Wheel on the rows"] = "在各列上使用滾輪"
L["Wheel: size. Right-click for more."] = "滾輪：大小。右鍵點擊查看更多。"
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "滾輪：文字大小。點擊一行以隱藏。右鍵點擊查看更多。"
L["When"] = "時機"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "當專業技能高到可以進階到下一等級（熟練、專精、大師）時，技能條下方和總覽中其卡片上的橫幅會說明所需條件和導師：最近的訓練師、書籍商人或任務給予者。點擊導航點即可在地圖上標記。達到時也會在聊天中提示一次；/naowh profrank 可再次顯示。"
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "你清單上的物品等待擲骰或出現在拾取視窗時，以及屬於你時。在 HUD 編輯器中移動畫面警示。"
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "NPC 提供多個選項時，直接前往可交付的已完成任務，或第一個可接的任務。可與上方兩個選項搭配使用。"
L["When it is up for a roll or drops."] = "等待擲骰或掉落時。"
L["When it is yours."] = "屬於你時。"
L["When You Leave"] = "你離開時"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "升級後有新法術可訓練時，通知會顯示數量和費用，並附上開啟規劃和設定前往最近訓練師導航點的按鈕。在 HUD 編輯器中移動。"
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "登出時，此角色上次儲存的組合會以你目前的快捷列、巨集和按鍵綁定再次儲存。"
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "到達城市或旅店時，畫面中央會閃爍顯示你缺少的物品清單。會一直顯示直到你補足或離開。在 HUD 編輯器中移動。"
L["When You Reset"] = "你重置時"
L["Where"] = "位置"
L["Where %s starts is not known."] = "%s 的起點未知。"
L["Where do you want to start?"] = "你想從哪裡開始？"
L["Where it comes from is not recorded yet; try the Auction House."] = "尚未記錄其來源；試試拍賣場。"
L["Where It Drops"] = "掉落地點"
L["Where on the frame the bar sits."] = "計量條在框架上的位置。"
L["Where to get them"] = "取得地點"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "你距離拉仇恨的差距和項目數的位置：在計量條下方，或在標題列和計量條之間。"
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "你的星號位置：在圖示角落、名稱前，或隱藏。"
L["Where? on Whispers"] = "密語上的在哪？"
L["Whether a healthstone or a potion comes first."] = "治療石或藥水哪個優先。"
L["Whether a new mark counts on every character or only this one."] = "新標記適用於所有角色或僅此角色。"
L["Whether NF Food leaves drinks to NF Drink."] = "NF Food 是否把飲料留給 NF Drink。"
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "你給此職業的祝福：力量、智慧、王者、拯救或光明。"
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "依技能選擇顯示哪些群體控制：所有等級，以及來自物品和生物的相同法術。"
L["Which debuffs show beside crowd control: off until you light them."] = "哪些減益效果顯示在群體控制旁：點亮前為關閉。"
L["Which guild and title lines show with players' names, saved by the game itself."] = "玩家名稱旁顯示哪些公會和頭銜行，由遊戲本身儲存。"
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "掃描背包會加入哪些消耗品類型，以及詢問是否新增會詢問哪些。"
L["Which mana spells get the line."] = "哪些法力法術會顯示該行。"
L["Which modules do you want?"] = "你想要哪些模組？"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "你的哪些選擇會警示：僅最佳裝備、前兩名，或清單上的每個選擇。"
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "兩者都攜帶時巨集優先使用哪個：治療石或治療藥水。"
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "商人開啟時，選定配方材料下方的購買按鈕會一鍵向其購買所有已勾選且其販售的材料（例如粗線或弱效助熔劑），數量為你在旁邊設定的製作次數。總費用顯示在按鈕旁；滑鼠指向購買可查看每種材料。"
L["While flying"] = "飛行時"
L["While flying and at the campfire"] = "飛行時和在營火旁"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "英勇打擊、順劈斬、槌擊或猛禽一擊排隊中時，近戰計量條會使用其顏色和名稱。"
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "拍賣場開啟時，選定配方材料下方的購買按鈕會購買你在旁邊設定的製作次數所需材料：所有已勾選且商人不販售的材料。每種會先顯示價格，只有在你點擊確認時才購買。"
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "拍賣場開啟時，選定配方名稱旁的搜尋拍賣場按鈕會搜尋該配方製作的物品。未學會的配方還有搜尋配方，用於搜尋教授它的圖樣、設計圖或手冊。不產出物品的配方（例如附魔）沒有搜尋拍賣場。"
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "拍賣場開啟時，Shift-點擊配方或材料可在拍賣場搜尋該物品：配方製作的物品或該材料。在聊天中打字時，Shift-點擊仍會連結它。"
L["While the mouse is away, with Show On Mouseover on."] = "滑鼠移開時，且開啟滑鼠指向時顯示。"
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "你在隊伍中時，將你從 NPC 接受的每個任務分享給其他人（若該任務可分享）。別人分享給你的任務不會再次分享。接受時按住修飾鍵則不分享。"
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "你攜帶書籍時，在收書者身上顯示標記：你的圖書館員，或法師訓練師。"
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "施法時，在主手計量條上標出施法結束的位置。揮擊到期時施法仍未結束則變紅。"
