L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "在畫面上顯示營地加成和剩餘時間，並在營地增益效果結束時提醒。"
L["Your camp's bonuses by the icon, always or while you hover it."] = "在圖示旁顯示營地加成，一直顯示或滑鼠指向時顯示。"
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "你的上限為 %d。\n請先完成任務 %s%s|r（%s技能 %d）："
