L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "最佳裝備清單風格的角色面板（C）：每個欄位及其標記、依你專精的屬性，以及等級下方的 Naowh 分數。遊戲會保留面板及其所有功能。搭配 EllesmereUI 時，開啟此選項會在重新載入後關閉其角色面板，關閉則會重新開啟。"
