L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "以小卡片顯示你的每小時經驗值，含升級時間、遊戲時間、階段長度和近期的升級時間。滿級時隱藏。滑鼠指向可開始、暫停和重置（也可用 /naowh xp start、pause 或 reset）。在 HUD 編輯器中移動。"
