L["Your focus's name, tinted by class, with their class icon above the panel."] = "你專注目標的名稱，依職業上色，面板上方顯示其職業圖示。"
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "以 NF Focus 設定的專注目標：你對付其他人時其計時器會繼續計算。"
L["Your game macros, not the Smart Macros, as one string to share."] = "你的遊戲巨集（不含智慧巨集），合成一個可分享的字串。"
